"""Choose the object store for generated bytes. Qiniu is used when it is configured."""

import asyncio

from app.core.config import Settings
from app.infrastructure.storage.qiniu import QiniuStorageProvider
from app.infrastructure.storage.s3 import S3Storage


class QiniuObjectStorage:
    provider_name = "qiniu"

    def __init__(self, settings: Settings, provider: QiniuStorageProvider | None = None) -> None:
        self._provider = provider or QiniuStorageProvider(settings)
        self.bucket_name = settings.qiniu_bucket.strip()

    async def put_object(self, *, object_key: str, content: bytes, content_type: str) -> None:
        await asyncio.to_thread(
            self._provider.upload_bytes,
            key=object_key,
            content=content,
            content_type=content_type,
        )

    async def get_object(self, *, object_key: str) -> bytes:
        url = await self.signed_download_url(object_key=object_key)
        return await asyncio.to_thread(_download, url)

    async def delete_object(self, *, object_key: str) -> None:
        await asyncio.to_thread(self._provider.delete, object_key)

    async def stat_object(self, *, object_key: str) -> int | None:
        stat = await asyncio.to_thread(self._provider.stat, object_key)
        return None if stat is None else stat.size

    async def signed_download_url(self, *, object_key: str) -> str:
        return await asyncio.to_thread(self._provider.private_download_url, object_key, 300)


def build_object_storage(settings: Settings):
    if settings.qiniu_configured:
        return QiniuObjectStorage(settings)
    return S3Storage(settings)


def _download(url: str) -> bytes:
    import ipaddress
    import urllib.request
    from urllib.parse import urlsplit

    parts = urlsplit(url)
    if parts.scheme not in {"http", "https"} or not parts.hostname:
        raise RuntimeError("object storage request failed")
    host = parts.hostname.rstrip(".").lower()
    if host == "localhost" or host.endswith(".local") or host.endswith(".internal"):
        raise RuntimeError("object storage request failed")
    try:
        address = ipaddress.ip_address(host)
    except ValueError:
        address = None
    if address is not None and (address.is_private or address.is_loopback or address.is_link_local):
        raise RuntimeError("object storage request failed")
    request = urllib.request.Request(url, method="GET")
    with urllib.request.urlopen(request, timeout=30) as response:
        return response.read()
